BEGIN;

DELETE FROM questions WHERE topic = 'Reproduction' AND subtopic IN ('Female Reproductive Anatomy', 'Gamete Structure & Fertilization', 'Male Reproductive Anatomy', 'Oogenesis', 'Spermatogenesis');

-- Q1 [Spermatogenesis | 2C | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub1$Spermatogenesis$sub1$, $qt1$A histologist examines a thin section of a human testis and marks the single structure in which spermatogonia divide and differentiate, ultimately giving rise to formed sperm. Which structure should the histologist mark as the site of sperm production?$qt1$, $op1$[{"label": "A", "text": "The seminiferous tubules, the coiled tubes whose walls consist of developing sperm cells"}, {"label": "B", "text": "The epididymis, the coiled tube attached to the testis where formed sperm mature"}, {"label": "C", "text": "The interstitial cells of Leydig located between the tubules of the testis"}, {"label": "D", "text": "The ductus deferens, the muscular tube that carries sperm out of the epididymis"}]$op1$::jsonb, 'A', $ex1$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is A because the seminiferous tubules are the coiled tubes that form the bulk of each testis, and their walls are built from developing sperm cells, making them the actual site where sperm are produced. OpenStax states that the seminiferous tubules are \"the site of sperm production\" and that they \"are composed of developing sperm cells surrounding a lumen,\" with germ cell development progressing from the basement membrane toward the lumen. Spermatogenesis—the process that begins with spermatogonia and concludes with formed sperm—occurs within these tubules; only after release do sperm move into the duct system. (Choice A) Correct: the seminiferous tubules house the spermatogonia, spermatocytes, and spermatids and are where sperm are produced. (Choice B) Incorrect: the epididymis is \"a coiled tube attached to the testis where newly formed sperm continue to mature,\" so it is a maturation and storage site, not a production site. (Choice C) Incorrect: Leydig (interstitial) cells lie between the tubules and produce testosterone, not sperm. (Choice D) Incorrect: the ductus deferens is a muscular tube that transports sperm from the epididymis, a transport duct downstream of where sperm are actually made. This is a Knowledge of Scientific Concepts and Principles question because it asks the student to recall and identify the specific anatomical site of spermatogenesis within the testis.$ex1$, 'easy', '2C', $cc1$Gametogenesis & Reproductive Anatomy (BIO)$cc1$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'adjacent_fact', $a1B$Confusing the site where sperm mature (epididymis) with the site where they are produced$a1B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a1C$Assuming the testosterone-producing Leydig cells make sperm because they reside within the testis$a1C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a1D$Selecting a downstream transport duct instead of the upstream production site$a1D$ FROM q;

-- Q2 [Spermatogenesis | 2C | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub2$Spermatogenesis$sub2$, $qt2$A histologist examines a cross-section of a seminiferous tubule and isolates the diploid (2n) cell lying directly against the basement membrane that divides by mitosis to both renew its own population and launch the production of sperm. Which cell has the histologist isolated?$qt2$, $op2$[{"label": "A", "text": "The secondary spermatocyte"}, {"label": "B", "text": "The spermatogonium"}, {"label": "C", "text": "The spermatid"}, {"label": "D", "text": "The spermatozoon"}]$op2$::jsonb, 'B', $ex2$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is B because the spermatogonium is the diploid (2n), undifferentiated stem cell that lines the basement membrane of the seminiferous tubule and divides by mitosis to begin spermatogenesis. OpenStax states that "Immediately under the capsule of the tubule are diploid, undifferentiated cells. These stem cells, called spermatogonia (singular: spermatagonium), go through mitosis with one offspring going on to differentiate into a sperm cell and the other giving rise to the next generation of sperm." The Anatomy text reinforces this, defining "spermatogonia (singular = spermatogonium) diploid precursor cells that become sperm" and noting they "line the basement membrane inside the tubule." Because the question asks for the diploid starting cell, the later haploid cells in the lineage are excluded. (Choice A) The secondary spermatocyte is haploid, produced at the end of meiosis I, so it is not the diploid starting cell. (Choice B) is correct because the spermatogonium is the diploid stem cell on the basement membrane that begins the lineage by mitosis. (Choice C) The spermatid is an immature haploid cell "produced by meiosis II of secondary spermatocytes," not the diploid precursor. (Choice D) The spermatozoon is the final haploid product of the process, not the diploid starting cell. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the identity and ploidy of a single named cell at a defined point in the spermatogenic lineage.$ex2$, 'easy', '2C', $cc2$Gametogenesis & Reproductive Anatomy (BIO)$cc2$, 'biology', 1, 70
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a2A$Confusing a haploid post-meiosis-I cell for the diploid stem cell$a2A$ FROM q
UNION ALL SELECT id, 'C', 'adjacent_fact', $a2C$Naming a real haploid lineage cell that is a later product rather than the precursor$a2C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a2D$Selecting the final product of the process instead of the starting cell$a2D$ FROM q;

-- Q3 [Spermatogenesis | 2C | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub3$Spermatogenesis$sub3$, $qt3$A histologist labels a single primary spermatocyte in the wall of a seminiferous tubule and follows it as it proceeds through spermatogenesis. She records the name of the cell that exists the instant the first meiotic division reaches completion, before any further division occurs. Which cell does she record at that moment?$qt3$, $op3$[{"label": "A", "text": "A spermatid, the cell formed at the conclusion of meiosis II"}, {"label": "B", "text": "A spermatogonium, the diploid stem cell of the tubule wall"}, {"label": "C", "text": "A secondary spermatocyte, the cell formed at the conclusion of meiosis I"}, {"label": "D", "text": "A spermatozoon, the flagellated cell released into the lumen"}]$op3$::jsonb, 'C', $ex3$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is C because, in the ordered sequence of spermatogenesis, the cell that exists immediately after the first meiotic division of a primary spermatocyte is the secondary spermatocyte. OpenStax states, "Meiosis starts with a cell called a primary spermatocyte. At the end of the first meiotic division, a haploid cell is produced called a secondary spermatocyte." The full pipeline runs spermatogonium to primary spermatocyte (meiosis I) to secondary spermatocyte (meiosis II) to spermatid, which then matures into a spermatozoon; the histologist is asking for the named stage that sits exactly one step downstream of meiosis I, which is the secondary spermatocyte. The two other meiotic products and the stem cell each occupy a different, identifiable position in that same sequence. (Choice A) A spermatid is a real spermatogenic cell, but the text places it at "the end of meiosis"—after the secondary spermatocyte goes "through another meiotic cell division"—so it is the product of meiosis II and lies one division too far downstream. (Choice B) A spermatogonium is the "diploid, undifferentiated" stem cell that feeds into spermatogenesis; it is the precursor that gives rise to the primary spermatocyte, not a cell produced by meiosis I. (Choice C) A secondary spermatocyte is correct because the text names it as the cell "produced" at "the end of the first meiotic division." (Choice D) A spermatozoon is the final stage, formed only after a spermatid "reaches the lumen of the tubule and grows a flagellum," so it lies at the very end of the pathway rather than just past meiosis I. This is a Scientific Reasoning and Problem Solving question because it requires placing a tracked cell at the correct position within the ordered spermatogenic sequence and distinguishing the immediate product of meiosis I from the stem-cell input and the later-stage products, rather than recalling a single isolated definition.$ex3$, 'medium', '2C', $cc3$Gametogenesis & Reproductive Anatomy (BIO)$cc3$, 'biology', 2, 100
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a3A$Names the product of meiosis II (spermatid) instead of meiosis I, advancing one division too far in the sequence$a3A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a3B$Names the spermatogonial stem cell that feeds INTO the pathway as if it were a product of meiosis I, reversing input and output$a3B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a3D$Names the correct lineage but jumps to the final flagellated spermatozoon stage instead of the cell just past meiosis I$a3D$ FROM q;

-- Q4 [Spermatogenesis | 2C | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub4$Spermatogenesis$sub4$, $qt4$In a research model, a toxin selectively destroys the elongate, branching sustentacular (Sertoli) cells lining a man's seminiferous tubules while leaving the interstitial cells, the tubule basement membrane, and the tubule lumen structurally intact. A physiologist is asked to predict the most direct consequence for the spermatogonia and other germ cells inside the affected tubules.$qt4$, $op4$[{"label": "A", "text": "Testosterone secretion collapses, but the surviving germ cells still complete spermatogenesis and release mature sperm."}, {"label": "B", "text": "Sperm continue to form normally but become trapped because the tubule lumen through which they exit is now obstructed."}, {"label": "C", "text": "The germ cells lose their blood–testis barrier yet still progress through meiosis and mature into normal sperm."}, {"label": "D", "text": "Sperm development fails because the germ cells lose the surrounding cells that nourish them and secrete signals promoting sperm production."}]$op4$::jsonb, 'D', $ex4$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is D because Sertoli (sustentacular) cells physically surround all stages of the developing germ cells and secrete signaling molecules that promote sperm production and control whether germ cells live or die; removing them removes the support spermatogenesis depends on. The text states that "Surrounding all stages of the developing sperm cells are elongate, branching Sertoli cells" and that "Sertoli cells secrete signaling molecules that promote sperm production and can control whether germ cells live or die," so destroying these cells deprives the germ cells of both their physical scaffold and their pro-spermatogenic signals, halting sperm development. The toxin spares the Leydig (interstitial) cells, the basement membrane, and the lumen, so the failure traces specifically to the loss of Sertoli support rather than to a hormone, transport, or barrier defect. (Choice A) is wrong because testosterone is a "steroid hormone produced by Leydig cells," which the toxin spares, so androgen output would not collapse, and germ cells deprived of Sertoli support cannot finish spermatogenesis. (Choice B) is wrong because the lumen is left intact and Sertoli loss disrupts the formation of sperm, not merely their exit through the "straight tubules" and ducts. (Choice C) is wrong because although the "tight junctions between these sustentacular cells create the blood–testis barrier," losing the Sertoli cells also removes their nourishing and signaling support, so germ cells cannot mature normally. (Choice D) is correct because the Sertoli cells supply the physical envelopment, nourishment, and survival/pro-spermatogenic signals without which the germ cells cannot develop into sperm. This is a Scientific Reasoning and Problem Solving question because it requires applying the defined roles of distinct seminiferous-tubule cell types to a selective-lesion scenario and predicting the downstream consequence rather than recalling a single stated fact.$ex4$, 'medium', '2C', $cc4$Gametogenesis & Reproductive Anatomy (BIO)$cc4$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a4A$Assigns the Leydig cells' testosterone-secreting role to Sertoli cells, so it predicts hormone collapse from a Sertoli lesion$a4A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a4B$Confuses a structural/transport role (lumen and duct conduction of sperm) with the Sertoli nourishing-support role$a4B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a4C$Correctly notes Sertoli tight junctions form the blood–testis barrier but ignores that losing Sertoli support also halts sperm maturation$a4C$ FROM q;

-- Q5 [Spermatogenesis | 2C | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub5$Spermatogenesis$sub5$, $qt5$A researcher labels a single human primary spermatocyte and follows its entire lineage through meiosis I, meiosis II, and the maturation steps that follow, counting how many functional gametes the labeled cell ultimately contributes to an ejaculate. Assuming every division proceeds normally, how many functional sperm does this one primary spermatocyte yield?$qt5$, $op5$[{"label": "A", "text": "Four functional spermatozoa, because meiosis I and meiosis II convert the primary spermatocyte into four spermatids that all mature into functional sperm"}, {"label": "B", "text": "One functional spermatozoon, because the unequal divisions of the primary spermatocyte produce a single gamete plus three nonfunctional polar bodies"}, {"label": "C", "text": "Two functional spermatozoa, because only the meiosis I division of the primary spermatocyte yields gametes that go on to mature"}, {"label": "D", "text": "Eight functional spermatozoa, because the primary spermatocyte first divides mitotically and both daughters then complete meiosis"}]$op5$::jsonb, 'A', $ex5$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is A because each primary spermatocyte completes meiosis I to give two secondary spermatocytes, and both of those complete meiosis II, producing a total of four haploid spermatids that each mature into a functional sperm. The text states that during meiosis I the primary spermatocyte yields two secondary spermatocytes "each with only half the number of chromosomes," after which "a second round of cell division (meiosis II) occurs in both of the secondary spermatocytes," so this "second meiotic division results in a total of four cells," each becoming a spermatid that is then transformed by spermiogenesis into a formed sperm. Spermatogenesis is symmetric: unlike oogenesis, no cytoplasm is partitioned unequally and no polar bodies are made, so all four products are retained as functional gametes. The key is recognizing that the meiotic arithmetic (one cell to four through two sequential divisions) applies fully to the male lineage. (Choice A) is correct: meiosis I plus meiosis II turns one primary spermatocyte into four spermatids, all of which mature into functional sperm. (Choice B) is wrong because the "one gamete plus three polar bodies" pattern is the unequal division of oogenesis, not spermatogenesis; importing polar bodies into the male lineage is the trap. (Choice C) is wrong because stopping after meiosis I counts only the two secondary spermatocytes and omits the second meiotic division that doubles the product to four. (Choice D) is wrong because the primary spermatocyte enters meiosis directly and is not preceded by an additional mitotic division of itself, so there is no eighth-fold expansion. This is a Scientific Reasoning and Problem Solving question because it requires chaining the sequential meiotic divisions of the male lineage to a numerical prediction and then distinguishing that prediction from the structurally similar but unequal output of oogenesis.$ex5$, 'hard', '2C', $cc5$Gametogenesis & Reproductive Anatomy (BIO)$cc5$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a5B$Correctly recalls the unequal-division/polar-body outcome of oogenesis but wrongly applies it to spermatogenesis; a 510-tempting trap$a5B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a5C$Stops the lineage after meiosis I and omits the second meiotic division$a5C$ FROM q
UNION ALL SELECT id, 'D', 'scale_unit_error', $a5D$Double-counts by inserting an extra mitotic round before meiosis, multiplying the four-cell yield to eight$a5D$ FROM q;

-- Q6 [Oogenesis | 2C | easy | Skill 1 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub6$Oogenesis$sub6$, $qt6$A developmental biologist examines the ovaries of a human fetus and a newborn infant and counts the cells that will eventually become eggs. She wants to determine the point at which the entire lifetime supply of egg-precursor cells is established. At what stage are oogonia produced and the pool of primary oocytes set?$qt6$, $op6$[{"label": "A", "text": "Oogonia continue dividing by mitosis throughout the reproductive years to renew the oocyte supply each cycle"}, {"label": "B", "text": "Oogonia form during fetal development and give rise to all primary oocytes before birth"}, {"label": "C", "text": "Oogonia first appear at puberty when anterior pituitary hormones activate the ovary"}, {"label": "D", "text": "Oogonia form in seminiferous-tubule-like cords and complete meiosis to mature gametes before birth"}]$op6$::jsonb, 'B', $ex6$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is B because oogonia arise during fetal development and produce the complete pool of primary oocytes in the fetal ovary prior to birth, so the finite supply is established prenatally and is never replenished afterward. The OpenStax Anatomy and Physiology text states that "Oogonia are formed during fetal development, and divide via mitosis" and that "oogonia form primary oocytes in the fetal ovary prior to birth," after which the primary oocytes arrest in meiosis I and only resume years later beginning at puberty. Because no new oogonia are made after fetal life, the number of primary oocytes only declines over the lifespan rather than being renewed. (Choice A) Unlike spermatogonia, which divide throughout life, oogonia do not keep dividing through the reproductive years; the supply is fixed before birth and steadily declines, so this reverses the female pattern by borrowing the male one. (Choice B) is correct because oogonia form during fetal development and establish the entire primary-oocyte pool before birth. (Choice C) Puberty is when arrested meiosis resumes and follicles develop under anterior pituitary hormones, not when oogonia first appear, since the cells were already present prenatally. (Choice D) Oogenesis occurs in the ovary, not in seminiferous tubules (the site of spermatogenesis), and oogonia form arrested primary oocytes rather than completing meiosis to mature gametes before birth. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established fact of when and where oogonia form and the lifetime oocyte pool is set.$ex6$, 'easy', '2C', $cc6$Gametogenesis & Reproductive Anatomy (BIO)$cc6$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a6A$Applies the lifelong mitotic division of male spermatogonia to female oogonia, implying continuous oocyte renewal$a6A$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a6C$Confuses puberty (resumption of arrested meiosis and follicle development) with the prenatal origin of oogonia$a6C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a6D$Borrows the seminiferous-tubule site of spermatogenesis and wrongly claims meiosis completes prenatally$a6D$ FROM q;

-- Q7 [Oogenesis | 2C | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub7$Oogenesis$sub7$, $qt7$A reproductive endocrinologist examines a single resting oocyte taken from the ovary of a healthy 25-year-old during the early follicular phase. She determines that this cell has been held in the same meiotic stage continuously since before the patient was born, and she wants to predict the specific physiological signal that will release it from that arrest. At what meiotic stage is the cell held, and what event triggers it to resume division?$qt7$, $op7$[{"label": "A", "text": "It is arrested in metaphase of meiosis II, and the pre-ovulatory luteinizing-hormone surge drives it to complete meiosis II"}, {"label": "B", "text": "It is arrested in prophase of meiosis I, and penetration of the cell by a sperm at fertilization triggers it to resume meiosis I"}, {"label": "C", "text": "It is arrested in prophase of meiosis I, and the pre-ovulatory luteinizing-hormone surge triggers it to resume and complete meiosis I"}, {"label": "D", "text": "It is arrested in prophase of meiosis I, and a threshold rise in follicle-stimulating hormone during the follicular phase triggers it to resume meiosis I"}]$op7$::jsonb, 'C', $ex7$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is C because the resting cell described is a primary oocyte, which forms in the fetal ovary before birth and is then arrested in prophase of meiosis I, only resuming meiosis years later when the pre-ovulatory luteinizing-hormone surge acts on it. The text states that oogonia "form primary oocytes in the fetal ovary prior to birth" and that "these primary oocytes are then arrested in this stage of meiosis I, only to resume it years later, beginning at puberty," which fixes both the cell identity and the arrest stage. It further specifies the trigger: "Just prior to ovulation, a surge of luteinizing hormone triggers the resumption of meiosis in a primary oocyte," initiating the transition from primary to secondary oocyte. Because the cell in the scenario has been held since before birth, it must be the primary oocyte in prophase I, and the named release signal is the LH surge, not FSH or fertilization. (Choice A) Metaphase-II arrest is the LATER block of the secondary oocyte, and that arrest is broken only at fertilization, not by the LH surge, so both the stage and the trigger are wrong here. (Choice B) The cell is correctly identified as a prophase-I primary oocyte, but sperm penetration completes meiosis II of the secondary oocyte ("Meiosis of a secondary oocyte is completed only if a sperm succeeds in penetrating its barriers"); it does not resume meiosis I. (Choice C) is correct: the primary oocyte sits in prophase I from before birth, and the pre-ovulatory LH surge triggers it to resume and complete meiosis I. (Choice D) names the right stage but the wrong hormone; the text identifies the luteinizing-hormone surge, not an FSH threshold, as the trigger that resumes meiosis. This is a Scientific Reasoning and Problem Solving question because it requires using the clue that the cell has been arrested since before birth to deduce the specific meiotic stage and then predict the precise hormonal signal that resumes division.$ex7$, 'medium', '2C', $cc7$Gametogenesis & Reproductive Anatomy (BIO)$cc7$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a7A$Confusing the later metaphase-II arrest of the secondary oocyte (released at fertilization) with the earlier prophase-I arrest of the primary oocyte (released by the LH surge)$a7A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a7B$Attributing the resumption of meiosis I to sperm penetration, when sperm penetration actually completes meiosis II of the secondary oocyte$a7B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a7D$Substituting follicle-stimulating hormone for the luteinizing-hormone surge named in the text as the trigger that resumes meiosis$a7D$ FROM q;

-- Q8 [Oogenesis | 2C | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub8$Oogenesis$sub8$, $qt8$A reproductive biologist images a single primary oocyte at the instant the preovulatory luteinizing-hormone surge drives it to finish meiosis I, then watches the immediate aftermath of that division. What cells and arrest state does the biologist observe right after meiosis I is completed?$qt8$, $op8$[{"label": "A", "text": "Two equal-sized secondary oocytes, each of which independently arrests at metaphase II"}, {"label": "B", "text": "One secondary oocyte plus one first polar body, with the secondary oocyte proceeding directly through meiosis II into a finished ovum"}, {"label": "C", "text": "One secondary oocyte plus one first polar body, with the secondary oocyte arrested at metaphase of meiosis I"}, {"label": "D", "text": "One secondary oocyte plus one first polar body, with the secondary oocyte arrested at metaphase of meiosis II"}]$op8$::jsonb, 'D', $ex8$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is D because completing meiosis I divides the primary oocyte's cytoplasm unequally, yielding one large secondary oocyte and one small first polar body, and the secondary oocyte then halts again specifically at metaphase II. The A&P text states that in this division "the cytoplasm is divided unequally, and one daughter cell is much larger than the other. This larger cell, the secondary oocyte... The smaller cell, called the first polar body" (A&P lines 56326-56329), so two products of unequal size are formed, not two identical cells. The Biology text then specifies the timing of the next pause: "A secondary meiotic arrest occurs, this time at the metaphase II stage" (Bio line 57235), and meiosis II only resumes "if a sperm succeeds in penetrating its barriers" (A&P line 56341). Thus the cell does not run straight to a finished ovum, and the arrest is at metaphase II rather than metaphase I. (Choice A) is wrong because cytokinesis is unequal, producing one secondary oocyte and one tiny polar body, not two equal secondary oocytes (A&P line 56327, "the cytoplasm is divided unequally"). (Choice B) names the correct two products but omits the second arrest; the secondary oocyte pauses rather than completing meiosis II immediately, which happens only upon sperm penetration (A&P lines 56340-56341). (Choice C) names the correct products but misplaces the arrest at metaphase I; the first arrest (prophase I) precedes this division, and the new arrest is at metaphase II (Bio line 57235). (Choice D) correctly pairs the unequal products with the metaphase II arrest. This is a Scientific Reasoning and Problem Solving question because it requires predicting the specific cellular products and the precise arrest stage of a multi-step process from a described experimental observation rather than restating a memorized definition.$ex8$, 'medium', '2C', $cc8$Gametogenesis & Reproductive Anatomy (BIO)$cc8$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a8A$Denies the unequal cytokinesis, assuming meiosis I yields two equivalent secondary oocytes$a8A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a8B$Correct products but omits the metaphase II arrest, treating meiosis II as continuous to the ovum$a8B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a8C$Correct products but assigns the second arrest to metaphase I instead of metaphase II$a8C$ FROM q;

-- Q9 [Oogenesis | 2C | hard | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub9$Oogenesis$sub9$, $qt9$A geneticist sequences mitochondrial DNA from a child, the child's mother, and the child's father and finds that the child's mtDNA matches the mother's exactly while sharing none of the variants unique to the father. Which feature of oogenesis best accounts for this strictly maternal transmission?$qt9$, $op9$[{"label": "A", "text": "Unequal cytokinesis partitions nearly all cytoplasm and organelles, including mitochondria, into the secondary oocyte rather than the polar body."}, {"label": "B", "text": "Unequal cytokinesis concentrates extra chromosomes in the secondary oocyte, giving the zygote a maternally biased chromosome complement."}, {"label": "C", "text": "Unequal cytokinesis loads the polar body with the bulk of the cytoplasm so the oocyte stays small and motile within the oviduct."}, {"label": "D", "text": "Retained cytoplasm lets the sperm's mitochondria amplify after fertilization, producing a mixed maternal-paternal mitochondrial pool."}]$op9$::jsonb, 'A', $ex9$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is A because the asymmetric division of oogenesis sends nearly all the cytoplasm and its organelles to the secondary oocyte, so the mitochondria the zygote inherits come from the egg alone. During oogenesis "the cytoplasm is divided unequally, and one daughter cell is much larger than the other...the secondary oocyte," while the polar body keeps almost none. Because "sperm contribute only DNA at fertilization—not cytoplasm," the text states that "the cytoplasm and all of the cytoplasmic organelles in the developing embryo are of egg-derived origin. This includes mitochondria," which were determined to be "maternally inherited." Chaining the asymmetric cytokinesis to the cytoplasm-only origin of the embryo's mitochondria explains why the child's mtDNA matches only the mother. (Choice A) Correct: the surviving gamete retains the cytoplasm and mitochondria, so all of the zygote's mtDNA is egg-derived and therefore maternal. (Choice B) Incorrect: the inequality of oogenesis is in cytoplasm, not chromosomes—each meiotic product receives "only one set of chromosomes," and mtDNA inheritance is unrelated to chromosome number. (Choice C) Incorrect: this reverses the partitioning—the secondary oocyte, not the polar body, keeps "the larger amount of cytoplasm," and the polar body simply degrades. (Choice D) Incorrect: sperm "contribute only DNA at fertilization—not cytoplasm," so no paternal mitochondria enter to be amplified, leaving the pool purely maternal. This is a Scientific Reasoning and Problem Solving question because it requires linking an observed sequencing result to the asymmetric cytoplasmic partitioning of oogenesis and the cytoplasm-only origin of embryonic organelles to predict why inheritance is strictly maternal.$ex9$, 'hard', '2C', $cc9$Gametogenesis & Reproductive Anatomy (BIO)$cc9$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a9B$Treats the unequal division as partitioning chromosomes rather than cytoplasm, conflating cytoplasmic asymmetry with chromosome number.$a9B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a9C$Reverses which cell keeps the cytoplasm, assigning the bulk to the polar body instead of the secondary oocyte.$a9C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a9D$510-tempting trap that forgets sperm contribute only DNA, inventing a mixed maternal-paternal mitochondrial pool via paternal amplification.$a9D$ FROM q;

-- Q10 [Oogenesis | 2C | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub10$Oogenesis$sub10$, $qt10$A researcher tracks one diploid germ cell entering meiosis in the testis and one diploid germ cell entering meiosis in the ovary, then counts how many functional gametes each ultimately produces under conditions that permit completion. She predicts the functional-gamete yield from each starting cell.$qt10$, $op10$[{"label": "A", "text": "The ovarian germ cell yields four functional ova and the testicular germ cell yields four functional sperm, matching meiosis's four-product output."}, {"label": "B", "text": "The ovarian germ cell yields one functional ovum and the testicular germ cell yields four functional sperm, with the ovarian process completing only upon sperm penetration."}, {"label": "C", "text": "The ovarian germ cell yields one functional ovum and the testicular germ cell yields one functional sperm, because the other meiotic products are discarded in both sexes."}, {"label": "D", "text": "The ovarian germ cell yields two functional ova and the testicular germ cell yields four functional sperm, one ovum arising from each completed meiotic division."}]$op10$::jsonb, 'B', $ex10$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is B because oogenesis routes nearly all cytoplasm to a single surviving ovum while the smaller products become polar bodies that degenerate, whereas spermatogenesis preserves all four meiotic products as functional sperm. In spermatogenesis, "Four sperm result from each primary spermatocyte that goes through meiosis," so one testicular germ cell yields four gametes. In oogenesis, the unequal divisions mean that "even though oogenesis produces up to four cells, only one survives," and "One egg is produced from each meiotic process, with the extra chromosomes and chromatids going into polar bodies that degenerate." Moreover, the secondary oocyte arrests at metaphase II and finishes meiosis II (producing the second polar body and the mature ovum) only "if the secondary oocyte is fertilized," so the single functional ovum is finalized only upon sperm penetration. (Choice A) is wrong because it ignores polar-body degeneration; oogenesis does not preserve four functional ova ("only one survives"). (Choice B) is correct: one ovum versus four sperm, with oogenesis completing conditionally at fertilization. (Choice C) is wrong because, although oogenesis yields one gamete, spermatogenesis keeps all four products ("Four sperm result from each primary spermatocyte"), not one. (Choice D) is wrong because oogenesis yields one ovum, not two; the larger cell of each unequal division is not an independent surviving gamete, since "only one survives." This is a Scientific Reasoning and Problem Solving question because it requires integrating the unequal cytoplasmic divisions of oogenesis, polar-body degeneration, and the conditional completion of meiosis II at fertilization to quantitatively predict and contrast functional-gamete yields across two processes.$ex10$, 'hard', '2C', $cc10$Gametogenesis & Reproductive Anatomy (BIO)$cc10$, 'biology', 2, 160
  ) RETURNING id
)
