SELECT id, 'A', 'misconception', $a10A$Assumes both sexes preserve all four meiotic products, ignoring polar-body degeneration in oogenesis$a10A$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a10C$Correct one-ovum count for oogenesis but wrongly applies single-gamete discarding to spermatogenesis$a10C$ FROM q
UNION ALL SELECT id, 'D', 'scale_unit_error', $a10D$Miscounts oogenesis yield by treating the larger cell of each division as a surviving gamete$a10D$ FROM q;

-- Q11 [Gamete Structure & Fertilization | 2C | easy | Skill 1 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub11$Gamete Structure & Fertilization$sub11$, $qt11$A researcher exposes motile human sperm to a drug that selectively poisons mitochondrial ATP synthesis but leaves all other organelles intact, and observes that the flagellum stops beating. Which region of the sperm cell normally houses the structures whose output the drug has blocked?$qt11$, $op11$[{"label": "A", "text": "The acrosome, the enzyme-filled cap that supplies the ATP used for flagellar swimming"}, {"label": "B", "text": "The head, whose compact haploid nucleus generates the ATP that drives the tail"}, {"label": "C", "text": "The mid-piece, whose tightly packed mitochondria generate the ATP that powers the flagellum"}, {"label": "D", "text": "The neck, where centriole-derived microtubules synthesize the ATP that powers motility"}]$op11$::jsonb, 'C', $ex11$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is C because the mid-piece is the region packed with mitochondria, and the ATP those mitochondria produce is what powers the flagellum. The text states that 'Tightly packed mitochondria fill the mid-piece of the sperm. ATP produced by these mitochondria will power the flagellum, which extends from the neck and the mid-piece through the tail of the sperm, enabling it to move the entire sperm cell.' A drug that poisons mitochondrial ATP synthesis therefore halts flagellar beating, and the mitochondria responsible are localized to the mid-piece. (Choice A) The acrosome is incorrect because it is a 'cap' on the head 'filled with lysosomal enzymes important for preparing sperm to participate in fertilization,' not a source of ATP. (Choice B) The head is incorrect because it 'contains the extremely compact haploid nucleus with very little cytoplasm'; the nucleus stores DNA and does not generate ATP. (Choice C) The mid-piece is correct because its tightly packed mitochondria produce the ATP that powers the flagellum and propels the sperm. (Choice D) The neck is incorrect because, although the flagellum's 'axial filament, is formed from one centriole,' that centriole builds the flagellar core rather than synthesizing ATP. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling which sperm region contains the mitochondria that supply ATP for flagellar motility.$ex11$, 'easy', '2C', $cc11$Gametogenesis & Reproductive Anatomy (BIO)$cc11$, 'biology', 1, 75
  ) RETURNING id
)
