SELECT id, 'A', 'misconception', $a11A$Treating the acrosome (a digestive-enzyme cap) as the sperm's energy source$a11A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a11B$Assigning ATP production to the DNA-containing head/nucleus$a11B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a11D$Confusing the centriole that builds the axial filament with an ATP-generating structure$a11D$ FROM q;

-- Q12 [Gamete Structure & Fertilization | 2C | medium | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub12$Gamete Structure & Fertilization$sub12$, $qt12$A researcher uses a micropipette to fully aspirate the contents of a capacitated human sperm's acrosomal cap, leaving the head's nucleus, the mitochondria-packed mid-piece, and the flagellum structurally intact, then places the cell beside a freshly ovulated oocyte still surrounded by its corona radiata and zona pellucida. Which outcome is the manipulation MOST likely to produce?$qt12$, $op12$[{"label": "A", "text": "The sperm becomes immotile but can still chemically dissolve a path through the zona pellucida toward the oocyte."}, {"label": "B", "text": "The sperm loses its haploid nucleus and therefore cannot contribute paternal DNA even if it reaches the oocyte."}, {"label": "C", "text": "The sperm still binds the zona pellucida receptors but can never trigger the oocyte's fast block to polyspermy."}, {"label": "D", "text": "The sperm still swims toward the oocyte but cannot clear a path through the zona pellucida to reach it."}]$op12$::jsonb, 'D', $ex12$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is D because the acrosome supplies the digestive enzymes that clear a path through the zona pellucida, whereas the energy for swimming comes from the mid-piece mitochondria powering the flagellum, so emptying the acrosome removes penetration ability while leaving motility intact. The acrosome is the enzyme-filled cap whose stored digestive enzymes \"clear a path through the zona pellucida that allows sperm to reach the oocyte\" (A&P 57447-57448), so without those contents the sperm cannot degrade the protective layer. Motility instead depends on a separate machine: \"ATP produced by these mitochondria will power the flagellum,\" which is housed in the mid-piece, not the head, and is left untouched by aspirating the acrosomal cap (A&P 55947-55948). Because the two functions reside in physically distinct regions, the manipulation isolates the loss of enzymatic penetration from the preserved capacity to swim. (Choice A) is reversed: the acrosome, not the mid-piece, supplies the dissolving enzymes, and the intact mid-piece mitochondria still power the flagellum, so the sperm stays motile but cannot dissolve the zona. (Choice B) is a misconception, because the haploid nucleus lies in the head distinct from the acrosomal cap that covers it, so emptying the acrosome does not remove the nucleus or the paternal DNA it carries (A&P 55943-55945). (Choice C) is a partial truth, because binding to zona pellucida receptors can still occur, but the fast block is a near-instantaneous change in sodium-ion permeability of the oocyte's own plasma membrane upon sperm binding and does not depend on the sperm's acrosomal contents (A&P 57477-57478). (Choice D) is correct because removing the acrosomal enzymes abolishes zona penetration while the mitochondria-driven flagellum preserves swimming. This is a Scientific Reasoning and Problem Solving question because it requires predicting the outcome of an experimental manipulation by separating the acrosome's digestive-enzyme function from the mid-piece's motility function and tracing each to its anatomical compartment.$ex12$, 'medium', '2C', $cc12$Gametogenesis & Reproductive Anatomy (BIO)$cc12$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a12A$Swaps the acrosome's digestive-enzyme role for the mid-piece's motility role, predicting immotility plus preserved dissolving ability$a12A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a12B$Conflates the acrosomal cap with the haploid nucleus it covers, treating loss of acrosomal contents as loss of nuclear DNA$a12B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a12C$Correct that zona binding still occurs but wrongly ties the oocyte-membrane fast block to acrosomal contents$a12C$ FROM q;

-- Q13 [Gamete Structure & Fertilization | 2C | medium | Skill 2 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub13$Gamete Structure & Fertilization$sub13$, $qt13$A clinician finds that a child has a mitochondrial-DNA disorder identical to the mother's, while the father carries no mtDNA mutation and the child's nuclear genome shows the expected biparental inheritance. Which feature of fertilization best accounts for the child inheriting the mitochondrial disease only from the mother?$qt13$, $op13$[{"label": "A", "text": "The ovum supplies essentially all of the zygote's cytoplasm, including its mitochondria, whereas the sperm contributes only DNA."}, {"label": "B", "text": "The sperm midpiece mitochondria fuse with the ovum's mitochondria and contribute an equal share of mitochondrial DNA to the zygote."}, {"label": "C", "text": "Mitochondrial DNA recombines like nuclear DNA at fertilization, so each parent transmits half of the zygote's mitochondrial genome."}, {"label": "D", "text": "The zona pellucida selectively admits only the maternal mitochondria while excluding paternal organelles during sperm binding."}]$op13$::jsonb, 'A', $ex13$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is A because the egg contributes the entire cytoplasmic compartment of the zygote, so every mitochondrion (and its DNA) in the embryo is egg-derived, making mtDNA disorders maternally inherited. The text states that "sperm contribute only DNA at fertilization—not cytoplasm. Therefore, the cytoplasm and all of the cytoplasmic organelles in the developing embryo are of egg-derived origin. This includes mitochondria, which contain their own DNA," and that mtDNA "was maternally inherited." Because the sperm delivers essentially only its nuclear chromosomes, any paternal mitochondria are not propagated, so a mtDNA mutation present in the mother's eggs is the only mitochondrial genome the child can receive. (Choice A) is correct: the ovum's large cytoplasm carries the mitochondria that populate the zygote, so the disease tracks the maternal line. (Choice B) is wrong because paternal mitochondria do not persist—mtDNA degrades in the sperm or the sperm's flagellar mitochondria fail to enter the egg—so there is no equal paternal contribution. (Choice C) is wrong because, unlike biparental nuclear DNA, mtDNA is inherited uniparentally from the mother rather than recombining and being passed half by each parent. (Choice D) is wrong because the zona pellucida mediates sperm binding and the acrosomal reaction, not the sorting of which mitochondria enter the zygote. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an inheritance pattern in a clinical scenario and tracing it back to the cell-biological mechanism of differential gamete cytoplasmic contribution.$ex13$, 'medium', '2C', $cc13$Gametogenesis & Reproductive Anatomy (BIO)$cc13$, 'biology', 2, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a13B$Paternal sperm mitochondria persist and contribute mtDNA equally to the zygote$a13B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a13C$Treating uniparental maternal mtDNA as if it recombined biparentally like nuclear DNA$a13C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a13D$Assigning organelle sorting to the zona pellucida, whose actual role is sperm binding$a13D$ FROM q;

-- Q14 [Gamete Structure & Fertilization | 2C | hard | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub14$Gamete Structure & Fertilization$sub14$, $qt14$A researcher fertilizes mouse oocytes in vitro and finds that a chelating agent that buffers intracellular free calcium ions leaves the brief membrane depolarization intact yet allows several sperm to bind and penetrate a single oocyte, producing triploid zygotes. The investigator concludes that the durable, receptor-destroying block to polyspermy has been disabled. Which event normally produces that durable block?$qt14$, $op14$[{"label": "A", "text": "A near-instantaneous rise in sodium-ion permeability depolarizes the oocyte membrane and provides the long-lasting block by permanently destroying the sperm receptors."}, {"label": "B", "text": "A calcium-ion influx triggers cortical granules beneath the oocyte membrane to release zonal inhibiting proteins that destroy the sperm receptors and harden the zona pellucida."}, {"label": "C", "text": "Acrosomal enzymes released by the fertilizing sperm re-harden the zona pellucida from the outside to exclude any further sperm from binding."}, {"label": "D", "text": "Completion of meiosis II expels a second polar body whose removal physically seals the oocyte membrane against additional sperm."}]$op14$::jsonb, 'B', $ex14$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is B because the durable, receptor-destroying block to polyspermy is the calcium-triggered slow block carried out by the cortical reaction. The text states that when the fast block lapses, "an influx of calcium ions following sperm penetration triggers the second mechanism, the slow block," in which "cortical granules sitting immediately below the oocyte plasma membrane fuse with the membrane and release zonal inhibiting proteins" that "destroy the oocyte's sperm receptors, thus preventing any more sperm from binding," while mucopolysaccharides "together with hardened zona pellucida" form a fertilization membrane. Because the experiment buffers calcium yet leaves depolarization intact, only this cortical, calcium-dependent step is disabled, so sperm receptors survive and polyspermy yields the lethal triploid zygote. (Choice A) The sodium-driven depolarization is the fast block, which "lasts for about a minute" and does not destroy receptors, so it cannot be the durable block, and it remained intact in the experiment. (Choice B) is correct because the calcium-triggered cortical granules release zonal inhibiting proteins that destroy sperm receptors and harden the zona, giving the lasting slow block. (Choice C) reverses the role of acrosomal enzymes, which "clear a path through the zona pellucida" by digesting it rather than hardening it; hardening comes from cortical-granule contents. (Choice D) confuses a later step: completing meiosis II merely stores excess genetic material in "a second polar body that is eventually ejected" and is not a polyspermy block. This is a Scientific Reasoning and Problem Solving question because it requires interpreting an experimental manipulation (calcium buffering with intact depolarization) to deduce which specific mechanistic step was eliminated and why that produces the triploid outcome.$ex14$, 'hard', '2C', $cc14$Gametogenesis & Reproductive Anatomy (BIO)$cc14$, 'biology', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a14A$Real sodium depolarization mislabeled as the durable, receptor-destroying block when it is the transient fast block$a14A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a14C$Acrosomal enzymes cast as hardening the zona when they actually degrade it$a14C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a14D$Meiosis II completion / polar body expulsion mistaken for the polyspermy block$a14D$ FROM q;

-- Q15 [Gamete Structure & Fertilization | 2C | hard | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub15$Gamete Structure & Fertilization$sub15$, $qt15$A reproductive biologist captures a single secondary oocyte at the instant a sperm successfully penetrates the zona pellucida and fuses with the oocyte membrane. She then films the cell continuously until it becomes a single-celled diploid zygote. Which sequence of events does she record from the moment of sperm penetration onward?$qt15$, $op15$[{"label": "A", "text": "The oocyte was already haploid at ovulation, so the sperm fuses directly with the ovum and no polar body forms before the genetic material combines."}, {"label": "B", "text": "Sperm entry restarts meiosis I, which halves the chromosome number, and then the sperm and oocyte pronuclei fuse to form the diploid zygote."}, {"label": "C", "text": "Sperm entry completes meiosis II, ejecting a second polar body to yield a haploid ovum, and then the sperm and oocyte pronuclei fuse to form the diploid zygote."}, {"label": "D", "text": "The sperm and oocyte pronuclei fuse first into a diploid nucleus, and the cell then completes meiosis II to discard the unneeded chromosomes as a second polar body."}]$op15$::jsonb, 'C', $ex15$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is C because sperm penetration is the trigger that resumes and completes meiosis II in the arrested secondary oocyte, and only after the unneeded chromosomes are expelled as the second polar body do the two haploid pronuclei fuse into the diploid zygote. The text states that "all secondary oocytes remain arrested in metaphase of meiosis II until fertilization. Only upon fertilization does the oocyte complete meiosis. The unneeded complement of genetic material that results is stored in a second polar body that is eventually ejected. At this moment, the oocyte has become an ovum, the female haploid gamete." Only after this does fertilization conclude: the pronuclei "migrate toward each other, their nuclear envelopes disintegrate, and the male- and female-derived genetic material intermingles... resulting in a single-celled diploid zygote." The completion of meiosis II therefore strictly precedes pronuclear fusion. (Choice A) is wrong because the oocyte is NOT haploid at ovulation; it is arrested in metaphase II and completes meiosis II (with a second polar body) only upon fertilization. (Choice B) is wrong because meiosis I is already finished before ovulation, so sperm entry triggers meiosis II, not meiosis I. (Choice C) is correct because it preserves the true order: meiosis II completion and second-polar-body ejection occur first, producing the haploid ovum, after which pronuclear fusion yields the diploid zygote. (Choice D) is wrong because it reverses the order: meiosis II must be completed to discard the extra chromosomes before the pronuclei fuse, not after. This is a Scientific Reasoning and Problem Solving question because it requires ordering a chain of late fertilization events from a scenario and predicting which step the sperm triggers rather than recalling a single isolated fact.$ex15$, 'hard', '2C', $cc15$Gametogenesis & Reproductive Anatomy (BIO)$cc15$, 'biology', 2, 150
  ) RETURNING id
)
