-- Q16 [Male Reproductive Anatomy | 3B | easy | Skill 1 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub16$Male Reproductive Anatomy$sub16$, $qt16$A clinician notes that a patient's testes are housed in the scrotum, which holds them away from the abdominal cavity, and explains that this external position is necessary for healthy sperm production. Which feature of the scrotal location accounts for its role in supporting normal spermatogenesis?$qt16$, $op16$[{"label": "A", "text": "It keeps the testes a few degrees warmer than core body temperature, which accelerates the rate of sperm production."}, {"label": "B", "text": "It shields the developing sperm from mechanical compression by the surrounding abdominal organs."}, {"label": "C", "text": "It increases the exposure of the testes to circulating testosterone, which drives faster sperm production."}, {"label": "D", "text": "It keeps the testes a few degrees cooler than core body temperature, the condition under which sperm production proceeds most efficiently."}]$op16$::jsonb, 'D', $ex16$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is D because the scrotum positions the testes outside the body cavity specifically to maintain a temperature below core body temperature, which is the condition that favors sperm production. OpenStax states that the scrotal location "is important in sperm production, which occurs within the testes, and proceeds more efficiently when the testes are kept 2 to 4°C below core body temperature." The dartos and cremaster muscles adjust the testes' distance from the body to fine-tune this slightly-cooler-than-core temperature, which confirms that cooling, not warming, is the operative requirement for efficient spermatogenesis. (Choice A) is incorrect because it reverses the requirement: the testes must be kept cooler than core temperature, not warmer, and an elevated temperature impairs rather than speeds sperm production. (Choice B) is incorrect because, although the testes are surrounded by protective tunica connective-tissue layers, the scrotum's external position serves a thermal function rather than a role in shielding sperm from compression by abdominal organs. (Choice C) is incorrect because, although the testes do produce testosterone and other androgens, the external scrotal location is about temperature regulation, not increased hormone exposure. (Choice D) is correct because housing the testes outside the abdominal cavity keeps them 2 to 4°C below core body temperature, the condition under which sperm production proceeds most efficiently. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the established anatomical function of the scrotum in maintaining the sub-core temperature needed for normal spermatogenesis.$ex16$, 'easy', '3B', $cc16$Gametogenesis & Reproductive Anatomy (BIO)$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a16A$Inverts the cooler-than-core requirement, claiming a warmer temperature speeds sperm production$a16A$ FROM q
