UNION ALL SELECT id, 'C', 'process_step_confusion', $a18C$Relocates the fructose role upstream to sperm production rather than downstream motility$a18C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a18D$Denies dependence on externally supplied fructose by inventing internal glycogen stores$a18D$ FROM q;

-- Q19 [Male Reproductive Anatomy | 3B | medium | Skill 2 | ans C]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub19$Male Reproductive Anatomy$sub19$, $qt19$A urologist labels a single mature sperm cell at the instant it is propelled out of the tail of the epididymis during ejaculation and tracks the structures it passes through until it exits the body. Which sequence of structures does the labeled sperm cell traverse, in order, from the epididymis to the point of exit?$qt19$, $op19$[{"label": "A", "text": "epididymis \\(\\rightarrow\\) ejaculatory duct \\(\\rightarrow\\) ductus (vas) deferens \\(\\rightarrow\\) urethra"}, {"label": "B", "text": "epididymis \\(\\rightarrow\\) ductus (vas) deferens \\(\\rightarrow\\) urethra \\(\\rightarrow\\) ejaculatory duct"}, {"label": "C", "text": "epididymis \\(\\rightarrow\\) ductus (vas) deferens \\(\\rightarrow\\) ejaculatory duct \\(\\rightarrow\\) urethra"}, {"label": "D", "text": "seminiferous tubule \\(\\rightarrow\\) epididymis \\(\\rightarrow\\) ductus (vas) deferens \\(\\rightarrow\\) ejaculatory duct"}]$op19$::jsonb, 'C', $ex19$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is C because, beginning from the epididymis, sperm pass into the ductus (vas) deferens, then through the ejaculatory duct, and finally exit by way of the urethra. The text states that "During ejaculation, sperm exit the tail of the epididymis and are pushed by smooth muscle contraction to the ductus deferens (also called the vas deferens)," establishing the epididymis-to-ductus-deferens step. It then describes that the fluid "next moves into the associated ejaculatory duct," and the glossary defines the ejaculatory duct as the duct that connects the ampulla of the ductus deferens with the duct of the seminal vesicle "at the prostatic urethra," placing the urethra as the final conduit to exit. Tracing these documented hand-offs gives epididymis → ductus deferens → ejaculatory duct → urethra. (Choice A) is incorrect because it swaps the order of the ductus deferens and the ejaculatory duct; sperm reach the ductus deferens first and only afterward enter the ejaculatory duct. (Choice B) is incorrect because it places the urethra before the ejaculatory duct, inverting the final two structures, whereas the ejaculatory duct empties into the urethra, not the reverse. (Choice C) is correct because it lists the documented proximal-to-distal sequence from the epididymis through the ductus deferens and ejaculatory duct to the urethral exit. (Choice D) is incorrect because, although seminiferous tubule → epididymis → ductus deferens → ejaculatory duct is a real proximal-to-distal sequence, it begins one structure too early (the question starts at the epididymis) and omits the urethra through which the sperm actually exits. This is a Scientific Reasoning and Problem Solving question because it requires applying knowledge of the male duct system to predict an ordered anatomical pathway from a starting point specified in the scenario rather than recalling an isolated definition.$ex19$, 'medium', '3B', $cc19$Gametogenesis & Reproductive Anatomy (BIO)$cc19$, 'biology', 2, 105
  ) RETURNING id
)
