UNION ALL SELECT id, 'B', 'reversed_relationship', $a19B$Inverts the directional relationship between the final two structures (urethra placed before the ejaculatory duct that drains into it)$a19B$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a19D$States a genuine adjacent sequence that begins one structure too early and omits the endpoint asked for$a19D$ FROM q;

-- Q20 [Male Reproductive Anatomy | 3B | hard | Skill 2 | ans D]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub20$Male Reproductive Anatomy$sub20$, $qt20$A urologist treats a patient whose prostate gland has been surgically removed, leaving the seminal vesicles, epididymides, and ductus deferentia intact. Compared with semen from a healthy male, the patient's ejaculate is predicted to differ in which way immediately after ejaculation?$qt20$, $op20$[{"label": "A", "text": "Sperm would lose their fructose fuel supply, because the removed gland was the source of the fructose that sperm mitochondria oxidize for motility."}, {"label": "B", "text": "The acidity of the semen would rise sharply, because the removed gland was the only source of alkaline secretion neutralizing the urethral and vaginal environment."}, {"label": "C", "text": "Sperm maturation would be incomplete, because secretions from the removed gland were required for sperm to acquire the ability to move on their own."}, {"label": "D", "text": "The semen would fail to coagulate and then liquefy normally, so it is less effectively retained in the female tract while sperm depend on seminal-vesicle fructose."}]$op20$::jsonb, 'D', $ex20$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is D because the prostate is the gland responsible for the alkaline secretion that first coagulates and then decoagulates semen, and this clot-then-liquefy step is what retains semen in the female reproductive tract. The text states the prostate "excretes an alkaline, milky fluid... that is critical to first coagulate and then decoagulate the semen following ejaculation. The temporary thickening of semen helps retain it within the female reproductive tract, providing time for sperm to utilize the fructose provided by seminal vesicle secretions." Removing the prostate eliminates this coagulation–liquefaction cycle, so semen is poorly retained during the very interval when sperm rely on seminal-vesicle fructose for motility; because the seminal vesicles remain intact, the fructose itself is still supplied, making the retention defect the key consequence. (Choice A) is wrong because the fructose used by sperm mitochondria comes from the seminal vesicles, not the prostate, and the seminal vesicles were left intact. (Choice B) is a partial truth: the prostate does secrete alkaline fluid, but the seminal vesicles also contribute alkaline fluid, so the prostate is not the sole buffer, and the text emphasizes the prostate's coagulation role rather than buffering as the unique critical function. (Choice C) misassigns the epididymis's role, since it is in the epididymis that sperm "further mature and acquire the ability to move under their own power," not the prostate. (Choice D) is correct because removing the prostate disrupts the coagulate-then-decoagulate retention step while seminal-vesicle fructose remains available. This is a Scientific Reasoning and Problem Solving question because it requires predicting the downstream physiological consequence of removing one accessory gland by chaining the prostate's coagulation function to the seminal vesicles' separate fructose contribution and reasoning about how the loss alters semen retention.$ex20$, 'hard', '3B', $cc20$Gametogenesis & Reproductive Anatomy (BIO)$cc20$, 'biology', 2, 160
  ) RETURNING id
)
