UNION ALL SELECT id, 'B', 'partial_truth', $a20B$Prostate does secrete alkaline fluid but is not the sole buffer; coagulation, not buffering, is the keyed critical role$a20B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a20C$Assigns the epididymis's sperm-maturation/motility-acquisition role to the prostate$a20C$ FROM q;

-- Q21 [Female Reproductive Anatomy | 3B | easy | Skill 1 | ans A]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub21$Female Reproductive Anatomy$sub21$, $qt21$A clinician describes a paired, almond-shaped pelvic organ in which each immature oocyte sits enclosed by a layer of supporting cells, and whose granulosa, theca, and luteal cells release the sex steroids estrogen and progesterone into the bloodstream. This organ is the:$qt21$, $op21$[{"label": "A", "text": "ovary, because its follicles enclose and protect immature oocytes while its follicular and luteal cells secrete estrogen and progesterone"}, {"label": "B", "text": "uterus, because its endometrium encloses and protects immature oocytes while its lining cells secrete estrogen and progesterone"}, {"label": "C", "text": "corpus luteum, because it encloses and protects immature oocytes while its luteal cells secrete estrogen and progesterone"}, {"label": "D", "text": "uterine tube, because its follicles enclose and protect immature oocytes while its tubal cells secrete estrogen and progesterone"}]$op21$::jsonb, 'A', $ex21$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is A because the ovary is the female gonad in which oocytes develop within the stroma, each surrounded by supporting cells to form a follicle, and whose follicular and luteal cells secrete the sex steroids estrogen and progesterone. The text states that in the ovary "Oocytes develop within the outer layer of this stroma, each surrounded by supporting cells. This grouping of an oocyte and its supporting cells is called a follicle," matching the immature-oocyte housing described. The text also confirms that LH "stimulates the granulosa and theca cells of the follicles to produce the sex steroid hormone estradiol, a type of estrogen," and that after ovulation "the luteinized granulosa and theca cells of the corpus luteum begin to produce large amounts of the sex steroid hormone progesterone," so estrogen and progesterone production both occur in cells of the ovary. (Choice A) is correct because only the ovary both houses the immature oocytes inside follicles and contains the cells (follicular and luteal) that secrete estrogen and progesterone. (Choice B) is wrong because the uterus is "the muscular organ that nourishes and supports the growing embryo" and its endometrium is the "site of implantation for the fertilized egg," not a site of oocyte storage or steroid synthesis. (Choice C) is wrong because the corpus luteum is a post-ovulatory ovarian remnant that secretes progesterone but forms only "after the oocyte has been ovulated," so it does not house immature oocytes. (Choice D) is wrong because the uterine tubes "serve as the conduit of the oocyte from the ovary to the uterus" and contain no follicles or steroid-producing cells. This is a Knowledge of Scientific Concepts and Principles question because it requires recalling the defined structure and endocrine function of the female gonad as described in the textbook.$ex21$, 'easy', '3B', $cc21$Gametogenesis & Reproductive Anatomy (BIO)$cc21$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
