-- Q22 [Female Reproductive Anatomy | 3B | medium | Skill 2 | ans B]
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'Reproduction', $sub22$Female Reproductive Anatomy$sub22$, $qt22$A reproductive physiologist exposes the inner mucosal lining of an excised uterine tube to a drug that abolishes the beating of its ciliated cells, then releases a freshly ovulated secondary oocyte into the infundibulum and observes its movement. Compared with an untreated tube, what is the MOST likely effect on the oocyte's transport toward the uterus?$qt22$, $op22$[{"label": "A", "text": "The oocyte is swept toward the uterus faster, because the smooth-muscle current now acts without the cilia opposing it."}, {"label": "B", "text": "The oocyte stalls and fails to be propelled toward the uterus, because it cannot move on its own and depends on the ciliary current for transport."}, {"label": "C", "text": "The oocyte propels itself toward the uterus with its own flagellum once the cilia stop assisting it."}, {"label": "D", "text": "The oocyte is unaffected and reaches the uterus normally, because the mucus-secreting cells, not the ciliated cells, drive its transport."}]$op22$::jsonb, 'B', $ex22$This is a Biology question that falls under the content category 'Gametogenesis & Reproductive Anatomy (BIO)'. The answer is B because the ovulated oocyte has no means of self-propulsion and relies on the cilia-generated current (along with smooth-muscle contractions) to carry it toward the uterus, so abolishing ciliary beating stalls its transport. The text states that "Unlike sperm, oocytes lack flagella, and therefore cannot move on their own" and that "Current flowing toward the uterus is generated by coordinated beating of the cilia that line the outside and lumen of the length of the uterine tube." The inner mucosa's "ciliated cells that beat in the direction of the uterus, produc[e] a current that will be critical to move the oocyte," confirming that loss of ciliary beating removes the force that propels the oocyte. (Choice A) is reversed: the cilia generate the uterus-directed current rather than oppose it, so removing them weakens, not accelerates, transport. (Choice B) is correct because the oocyte cannot move on its own and depends on the ciliary current for propulsion toward the uterus. (Choice C) is a misconception, since oocytes lack flagella entirely and cannot swim like sperm. (Choice D) is wrong because it is the ciliated cells, not the mucus-secreting cells, that generate the propulsive current. This is a Scientific Reasoning and Problem Solving question because it requires predicting the functional consequence of an experimental manipulation by linking the oocyte's lack of self-propulsion to its dependence on ciliary current.$ex22$, 'medium', '3B', $cc22$Gametogenesis & Reproductive Anatomy (BIO)$cc22$, 'biology', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
